"use client";

import { motion, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";

import { CheckIcon } from "../parts/icons";
import { BlockFrame } from "../parts/block-frame";
import { EVENTS, type EventKind, type FeedEvent, INCOMING, KINDS } from "./activity-feed/data";
import { EventRow } from "./activity-feed/event-row";
import { NewUpdates } from "./activity-feed/new-updates";
import { useTimeouts } from "./shared/use-timeouts";

type Filter = "all" | EventKind;

const FILTERS: Filter[] = ["all", "comment", "change", "release", "file"];

const DAYS = [
  { id: "today", label: "Today", date: "Oct 31" },
  { id: "yesterday", label: "Yesterday", date: "Oct 30" },
] as const;

/** How long the read line takes to travel the list, in milliseconds. */
const SWEEP_MS = 700;
/** How often a new event arrives while the feed is open. */
const ARRIVAL_MS = 6000;

/**
 * A team activity feed, grouped by day. People filter by kind, open an event
 * for its details, bring in events that arrived while they read, and mark
 * everything read with a line that clears each dot as it passes.
 */
export function ActivityFeed({ className }: { className?: string }) {
  const [events, setEvents] = useState<FeedEvent[]>(EVENTS);
  const [queued, setQueued] = useState<FeedEvent[]>([]);
  const [fresh, setFresh] = useState<Set<string>>(new Set());
  const [filter, setFilter] = useState<Filter>("all");
  const [open, setOpen] = useState<string | null>(null);
  const [sweep, setSweep] = useState(0);
  const arrived = useRef(0);
  const later = useTimeouts();
  const reduceMotion = useReducedMotion();
  const titleId = useId();

  // New events arrive one at a time and wait behind the button, so the list never jumps under the reader.
  useEffect(() => {
    const timer = window.setInterval(() => {
      const next = INCOMING[arrived.current];
      if (!next) {
        window.clearInterval(timer);
        return;
      }
      arrived.current += 1;
      setQueued((list) => [...list, next]);
    }, ARRIVAL_MS);
    return () => window.clearInterval(timer);
  }, []);

  const unread = events.filter((event) => event.unread).length;
  const visible = filter === "all" ? events : events.filter((event) => event.kind === filter);
  const count = (kind: Filter) => (kind === "all" ? events.length : events.filter((event) => event.kind === kind).length);

  const filters: { value: Filter; label: ReactNode }[] = FILTERS.map((value) => ({
    value,
    label: (
      <span className="flex items-center gap-1.5 whitespace-nowrap">
        {value === "all" ? "All" : KINDS[value].label}
        <span className="text-xs tabular-nums opacity-70">{count(value)}</span>
      </span>
    ),
  }));

  const markRead = (ids: string[]) =>
    setEvents((list) => list.map((event) => (ids.includes(event.id) ? { ...event, unread: false } : event)));

  const showQueued = () => {
    setFresh(new Set(queued.map((event) => event.id)));
    setEvents((list) => [...[...queued].reverse(), ...list]);
    setQueued([]);
  };

  const markAllRead = () => {
    if (reduceMotion) {
      markRead(events.map((event) => event.id));
      return;
    }
    // The line passes each visible row in turn; rows the filter hides clear when it lands.
    setSweep((value) => value + 1);
    visible.forEach((event, index) => {
      if (event.unread) later(() => markRead([event.id]), ((index + 0.5) / visible.length) * SWEEP_MS);
    });
    later(() => markRead(events.map((event) => event.id)), SWEEP_MS);
  };

  const toggle = (event: FeedEvent) => {
    setOpen((current) => (current === event.id ? null : event.id));
    if (event.unread) markRead([event.id]);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 px-5 pt-4">
        <h2 id={titleId} className="flex items-baseline gap-2 text-base font-semibold">
          Activity
          <span role="status" className="text-sm font-normal tabular-nums text-muted-foreground">
            {unread === 0 ? "All read" : `${unread} unread`}
          </span>
        </h2>
        <Button type="button" variant="outline" size="sm" onClick={markAllRead} disabled={unread === 0}>
          <CheckIcon aria-hidden="true" className="size-4" />
          Mark all read
        </Button>
      </header>

      <div className="scroll-fade-effect-x scrollbar-none overflow-x-auto px-5 pt-3 pb-1">
        <SegmentedControl aria-label="Kind of event" options={filters} value={filter} onValueChange={setFilter} />
      </div>

      <NewUpdates queued={queued} onShow={showQueued} />

      <div className="scroll-fade-effect-y scrollbar-none relative max-h-120 overflow-y-auto px-2 pt-2 pb-3">
        <div className="relative">
          {sweep > 0 && !reduceMotion ? (
            <motion.span
              key={sweep}
              aria-hidden="true"
              initial={{ top: "0%", opacity: 1 }}
              animate={{ top: "100%", opacity: [1, 1, 0] }}
              transition={{ duration: SWEEP_MS / 1000, ease: "linear" }}
              className="pointer-events-none absolute inset-x-3 z-10 h-px bg-chart-1"
            />
          ) : null}
          {DAYS.map((day) => {
            const rows = visible.filter((event) => event.day === day.id);
            if (rows.length === 0) return null;
            return (
              <section key={day.id} aria-label={`${day.label}, ${day.date}`} className="pt-2">
                <h3 className="px-3 pb-1 text-xs font-medium text-muted-foreground">
                  {day.label} <span className="font-normal">{day.date}</span>
                </h3>
                <ul className="flex flex-col">
                  {rows.map((event) => (
                    <EventRow key={event.id} event={event} expanded={open === event.id} onToggle={() => toggle(event)} fresh={fresh.has(event.id)} />
                  ))}
                </ul>
              </section>
            );
          })}
          {visible.length === 0 ? <p className="px-3 py-8 text-center text-sm text-muted-foreground">Nothing of this kind yet.</p> : null}
        </div>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

