import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { ChevronDownIcon } from "../../parts/icons";
import { PersonAvatar } from "../shared/person-avatar";
import { HUE_TILE, PEOPLE } from "../shared/people";
import { type FeedEvent, KINDS } from "./data";

/** Props for one event in the activity feed. */
export interface EventRowProps {
  event: FeedEvent;
  expanded: boolean;
  /** Opens or closes the details, and marks the event read. */
  onToggle: () => void;
  /** Whether the event just arrived, so it slides in rather than appearing. */
  fresh: boolean;
}

/**
 * One event: an avatar with a badge for its kind, the sentence, a context
 * line, the time and an unread dot. The whole row is a button that opens the
 * details below it.
 */
export function EventRow({ event, expanded, onToggle, fresh }: EventRowProps) {
  const reduceMotion = useReducedMotion();
  const detailId = useId();
  const person = PEOPLE[event.actor];
  const kind = KINDS[event.kind];
  const KindIcon = kind.icon;

  return (
    <motion.li
      layout={reduceMotion ? false : "position"}
      initial={fresh && !reduceMotion ? { opacity: 0, y: -12 } : false}
      animate={{ opacity: 1, y: 0 }}
      transition={{ type: "spring", stiffness: 380, damping: 38 }}
      className="relative"
    >
      <Button
        type="button"
        variant={expanded ? "secondary" : "ghost"}
        size="sm"
        aria-expanded={expanded}
        aria-controls={detailId}
        onClick={onToggle}
        className="w-full justify-start text-left whitespace-normal"
      >
        <span className="flex w-full items-start gap-3 px-3 py-2.5 font-normal">
        <span className="relative mt-0.5">
          <PersonAvatar person={person} />
          <span className={cn("absolute -right-1 -bottom-1 flex size-4 items-center justify-center rounded-full ring-2 ring-card", HUE_TILE[kind.hue])}>
            <KindIcon aria-hidden="true" className="size-2.5" />
          </span>
        </span>
        <span className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className="text-sm text-muted-foreground">
            <span className="font-medium text-foreground">{person.name}</span> {event.action}{" "}
            <span className="font-medium text-foreground">{event.object}</span>
          </span>
          <span className="truncate text-xs text-muted-foreground">{event.context}</span>
        </span>
        <span className="flex shrink-0 items-center gap-2 pt-0.5">
          <span className="text-xs tabular-nums text-muted-foreground">{event.time}</span>
          <span
            aria-hidden="true"
            className={cn("size-2 rounded-full bg-chart-1 motion-safe:transition-transform motion-safe:duration-300", event.unread ? "scale-100" : "scale-0")}
          />
          {event.unread ? <span className="sr-only">Unread</span> : null}
          <ChevronDownIcon aria-hidden="true" className={cn("size-3.5 text-muted-foreground motion-safe:transition-transform", expanded && "rotate-180")} />
        </span>
        </span>
      </Button>
      <AnimatePresence initial={false}>
        {expanded ? (
          <motion.div
            key="detail"
            id={detailId}
            initial={reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
            animate={reduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
            exit={reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
            transition={{ duration: 0.22, ease: [0.2, 0, 0, 1] }}
            className="overflow-hidden"
          >
            <p className="ml-14 mr-3 mb-3 border-l-2 border-border pl-3 text-sm text-foreground">{event.detail}</p>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </motion.li>
  );
}

import { cn } from "@/lib/utils";

import { HUE_TILE, type Person, initials } from "./people";

const SIZE = {
  sm: "size-6 text-[0.625rem]",
  md: "size-8 text-xs",
  lg: "size-10 text-sm",
} as const;

/** Props for a round initials avatar. */
export interface PersonAvatarProps {
  person: Person;
  size?: keyof typeof SIZE;
  className?: string;
}

/**
 * A round avatar with a person's initials on their own tint. It is decorative:
 * the name always sits beside it in text.
 */
export function PersonAvatar({ person, size = "md", className }: PersonAvatarProps) {
  return (
    <span
      aria-hidden="true"
      className={cn("inline-flex shrink-0 select-none items-center justify-center rounded-full font-semibold", SIZE[size], HUE_TILE[person.hue], className)}
    >
      {initials(person.name)}
    </span>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";

import { ArrowUpIcon } from "../../parts/icons";
import { PersonAvatar } from "../shared/person-avatar";
import { PEOPLE } from "../shared/people";
import type { FeedEvent } from "./data";

/** Props for the row that holds events waiting to be shown. */
export interface NewUpdatesProps {
  queued: FeedEvent[];
  onShow: () => void;
}

/**
 * The row above the list that appears when events are waiting. It takes its
 * own space, so it never covers an event, and folds away once they are shown.
 */
export function NewUpdates({ queued, onShow }: NewUpdatesProps) {
  const reduceMotion = useReducedMotion();
  const count = queued.length;
  return (
    <AnimatePresence initial={false}>
      {count > 0 ? (
        <motion.div
          key="new-updates"
          initial={reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
          animate={reduceMotion ? { opacity: 1 } : { height: "auto", opacity: 1 }}
          exit={reduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }}
          transition={{ duration: 0.24, ease: [0.2, 0, 0, 1] }}
          className="overflow-hidden"
        >
          <div className="flex justify-center pt-3">
            <Button type="button" variant="outline" size="sm" onClick={onShow}>
              <span aria-hidden="true" className="flex -space-x-1.5">
                {queued.slice(0, 3).map((event) => (
                  <PersonAvatar key={event.id} person={PEOPLE[event.actor]} size="sm" className="ring-2 ring-background" />
                ))}
              </span>
              {count === 1 ? "1 new update" : `${count} new updates`}
              <ArrowUpIcon aria-hidden="true" className="size-3.5" />
            </Button>
          </div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";

/**
 * Schedules timers that are all cleared when the component unmounts, so a
 * simulated reply never lands on a block that is gone. Returns `later(run, ms)`.
 */
export function useTimeouts() {
  const ids = useRef(new Set<number>());
  useEffect(() => {
    const pending = ids.current;
    return () => {
      for (const id of pending) window.clearTimeout(id);
      pending.clear();
    };
  }, []);
  return useCallback((run: () => void, ms: number) => {
    const id = window.setTimeout(() => {
      ids.current.delete(id);
      run();
    }, ms);
    ids.current.add(id);
    return id;
  }, []);
}
